import { ArchiveData, hash } from "./Cache.js";
import { decode as fastAtob } from "base64-arraybuffer-es6";
export class FlatIndexData {
    id;
    revision;
    compression;
    crc;
    named;
    /**@internal*/ archives = new Map();
    constructor(id) {
        this.id = id;
    }
    static async of(indexID, data) {
        const LF = 0x0A;
        const EQ = 0x3D;
        let fid = new FlatIndexData(indexID);
        const td = new TextDecoder();
        let ar;
        for (let i = 0; i < data.length; i++) {
            let eol = data.indexOf(LF, i);
            if (eol == -1) {
                eol = data.length;
            }
            let line = data.subarray(i, eol);
            i = eol;
            let kvs = line.indexOf(EQ);
            if (kvs == -1) {
                continue;
            }
            let key = td.decode(line.subarray(0, kvs));
            let value = td.decode(line.subarray(kvs + 1));
            if (key === "id") {
                fid.archives.set(~~value, ar = new ArchiveData(indexID, ~~value));
                continue;
            }
            if (!ar) {
                switch (key) {
                    case "named":
                        fid.named = value == "true";
                        break;
                    case "revision":
                    case "compression":
                    case "crc":
                        fid[key] = ~~value;
                        break;
                }
            }
            else {
                switch (key) {
                    case "contents": {
                        ar.compressedData = new Uint8Array(fastAtob(value));
                        break;
                    }
                    case "file": {
                        let [id, hash] = value.split("=");
                        ar.addFile(~~id, ~~hash);
                        break;
                    }
                    case "namehash":
                    case "revision":
                    case "crc":
                        ar[key] = ~~value;
                        break;
                    case "compression":
                        break;
                }
            }
        }
        return fid;
    }
    getArchive(archive) {
        return this.archives.get(archive);
    }
    getArchiveByName(name) {
        let namehash = hash(name);
        for (let ar of this.archives.values()) {
            if (ar.namehash == namehash) {
                return ar;
            }
        }
    }
}
export class FlatCacheProvider {
    disk;
    indexes = new Map();
    constructor(disk) {
        this.disk = disk;
    }
    async getIndex(index) {
        let idxp = this.indexes.get(index);
        if (!idxp) {
            this.indexes.set(index, idxp = this.disk.getFile(index + ".flatcache").then(data => data && FlatIndexData.of(index, data)));
        }
        return idxp;
    }
    async getArchive(index, archive) {
        let idx = await this.getIndex(index);
        return idx?.getArchive(archive);
    }
    async getArchives(index) {
        let idx = await this.getIndex(index);
        if (!idx) {
            return;
        }
        return Array.from(idx.archives.keys());
    }
    async getArchiveByName(index, name) {
        let idx = await this.getIndex(index);
        return idx?.getArchiveByName(name);
    }
    async getVersion(index) {
        return {
            era: "osrs",
            indexRevision: (await this.getIndex(index))?.revision ?? 0,
        };
    }
}
